<main class="content"><header class="topbar"><div><span class="eyebrow">Segurança</span><h1>Acessos e auditoria</h1></div><a class="button" href="/admin">Voltar</a></header><section class="panel"><h2>Atribuir perfil e escopo</h2><form method="post" action="/admin/access/assign"><input type="hidden" name="_csrf" value="<?=View::e(Security::csrfToken())?>"><div class="form-grid"><label>Usuário<select name="user_id"><?php foreach($users as $user): ?><option value="<?=$user['id']?>"><?=View::e($user['name'].' · '.$user['email'])?></option><?php endforeach; ?></select></label><label>Perfil<select name="role_id"><?php foreach($roles as $role): ?><option value="<?=$role['id']?>"><?=View::e($role['name'])?></option><?php endforeach; ?></select></label><label>Organização<input type="number" name="organization_id" min="1"></label><label>Projeto<input type="number" name="project_id" min="1"></label><label>Campeonato<input type="number" name="tournament_id" min="1"></label><label>Equipe<input type="number" name="team_id" min="1"></label></div><button class="button primary" type="submit">Atribuir acesso</button></form></section><section class="panel"><h2>Permissões por perfil</h2><div class="table-wrap"><table><thead><tr><th>Perfil</th><th>Permissões</th></tr></thead><tbody><?php foreach($roles as $role): ?><tr><td><?=View::e($role['name'])?></td><td><?=View::e($role['permissions']??'')?></td></tr><?php endforeach; ?></tbody></table></div></section><section class="panel"><h2>Atribuições ativas</h2><div class="table-wrap"><table><thead><tr><th>Usuário</th><th>Perfil</th><th>Org</th><th>Projeto</th><th>Campeonato</th><th>Equipe</th></tr></thead><tbody><?php foreach($assignments as $a): ?><tr><td><?=View::e($a['user_name'])?></td><td><?=View::e($a['role_name'])?></td><td><?=View::e($a['organization_id']??'')?></td><td><?=View::e($a['project_id']??'')?></td><td><?=View::e($a['tournament_id']??'')?></td><td><?=View::e($a['team_id']??'')?></td></tr><?php endforeach; ?></tbody></table></div></section><section class="panel"><h2>Auditoria recente</h2><div class="table-wrap"><table><thead><tr><th>Quando</th><th>Usuário</th><th>Ação</th><th>Entidade</th><th>Escopo</th></tr></thead><tbody><?php foreach($audit as $entry): ?><tr><td><?=View::e($entry['created_at'])?></td><td><?=View::e($entry['user_name']??'Sistema')?></td><td><?=View::e($entry['action'])?></td><td><?=View::e($entry['entity_type'].' #'.($entry['entity_id']??''))?></td><td><?=View::e('O'.$entry['organization_id'].' P'.$entry['project_id'].' C'.$entry['tournament_id'].' E'.$entry['team_id'])?></td></tr><?php endforeach; ?></tbody></table></div></section></main>
